sysauto_script.script:
(function() {
    var today = new GlideDateTime();
    today.addDaysUTC(30);
    var targetDate = today.getDate().toString();

    var gr = new GlideRecord('x_848842_techdesk_asset');
    gr.addQuery('warranty_expiry', targetDate);
    gr.addQuery('lifecycle_state', 'deployed');
    gr.query();

    while (gr.next()) {
        var assetTag = gr.getValue('asset_tag');
        var assignedTo = gr.assigned_to.getDisplayValue();
        gs.info('TechDesk Warranty Expiry: Asset ' + assetTag + ' assigned to ' + assignedTo + ' has warranty expiring in 30 days');
    }
})();
